export const articleBySlug = (slug: string) => LEARNING_ARTICLES.find((a) => a.slug === slug) ?? null;
export const articleByN = (n: number) => LEARNING_ARTICLES.find((a) => a.n === n) ?? null;
export const articlePath = (a: { slug: string }) => `/learning/articles/${a.slug}`;
